function probability(width) {
  const n = 160;
  const h = width / n;
  let total = density(0) + density(width);
  for (let i = 1; i < n; i++) total += (i % 2 === 0 ? 2 : 4) * density(i * h);
  return 2 * total * h / 3;
}

